python - <<'PY'
from more_itertools import interleave_evenly, sliced, numeric_range
from decimal import Decimal
from fractions import Fraction
from datetime import datetime, timedelta
from itertools import product

for inputs in ([], (), [[]], [[], []], [[], [], []]):
    assert list(interleave_evenly(inputs)) == []
    assert list(interleave_evenly(inputs, lengths=[0] * len(inputs))) == []
for lengths in product(range(5), repeat=4):
    inputs = [[(i, j) for j in range(n)] for i, n in enumerate(lengths)]
    result = list(interleave_evenly(inputs))
    assert sorted(result) == sorted(x for seq in inputs for x in seq)
    for i, seq in enumerate(inputs):
        assert [x for x in result if x[0] == i] == seq
for seq in ([], [1, 2, 3], 'abc'):
    for strict in (False, True):
        for size in (-1, -2, -100):
            try:
                sliced(seq, size, strict=strict)
            except ValueError:
                pass
            else:
                raise AssertionError((seq, size, strict))
        assert list(sliced(seq, 0, strict=strict)) == []
for start, stop, step in product(range(-5, 6), range(-5, 6), range(-5, 6)):
    if not step:
        continue
    r = numeric_range(start, stop, step)
    assert list(reversed(r)) == list(r)[::-1]
for cls in (float, Decimal, Fraction):
    for start, stop, step in (('0', '1', '0.1'), ('1', '0', '-0.1'),
                              ('0.3', '1.7', '0.2'), ('1', '1', '0.2'),
                              ('0', '1', '-0.1'), ('1', '0', '0.1')):
        r = numeric_range(cls(start), cls(stop), cls(step))
        assert list(reversed(r)) == list(r)[::-1], (cls, start, stop, step)
for start, stop, step in ((datetime.min, datetime.min + timedelta(days=3), timedelta(days=1)),
                          (datetime.max, datetime.max - timedelta(days=3), -timedelta(days=1)),
                          (datetime.min, datetime.min, timedelta(days=1))):
    r = numeric_range(start, stop, step)
    assert list(reversed(r)) == list(r)[::-1]
print('Targeted regression checks passed')
PY
